// Regenerate src/lib/db/seed-sql.generated.ts from supabase/seed.sql.
// Run after editing seed.sql:  npm run db:gen-seed
// Why: the reset route runs on Vercel serverless, where reading repo files at runtime is fragile,
// so the app imports the seed as a string module. A unit test fails if the two drift.
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = join(import.meta.dirname, "..");
const seed = readFileSync(join(root, "supabase", "seed.sql"), "utf8").replace(/\r\n/g, "\n");
const out =
  "// GENERATED by scripts/db-gen-seed.mjs from supabase/seed.sql. Do not edit by hand.\n" +
  "// Run `npm run db:gen-seed` after changing supabase/seed.sql.\n" +
  `export const SEED_SQL: string = ${JSON.stringify(seed)};\n`;
writeFileSync(join(root, "src", "lib", "db", "seed-sql.generated.ts"), out);
console.log("wrote src/lib/db/seed-sql.generated.ts");
